import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, uniform, positionLocal, mix, smoothstep, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Color, DoubleSide } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38'
  };
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' }, { at: 1, hex: '#12121a' }
  ];

  const items = config.textContent ?? spec.textContent ?? [];
  const getText = (role, fallback) => {
    const found = items.find((i) => i.role === role);
    return found ? found.text : fallback;
  };
  const captions = items.filter((i) => i.role === 'caption').map((i) => i.text);
  const captionList = captions.length ? captions : [
    'NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL', 'NA-04 VANTAGE', 'NA-05 ARCHIVE'
  ];

  const group = new Group();
  const timelines = [];
  const primitiveHandles = [];
  const disposables = [];

  // ---- Backdrop stage plane with vertical gradient ----
  const topCol = new Color(gradientStops[gradientStops.length - 1].hex);
  const botCol = new Color(gradientStops[0].hex);
  const bgMat = new MeshBasicNodeMaterial();
  const tY = positionLocal.y.mul(0.5).add(0.5);
  bgMat.colorNode = mix(
    vec3(botCol.r, botCol.g, botCol.b),
    vec3(topCol.r, topCol.g, topCol.b),
    smoothstep(0.0, 1.0, tY)
  );
  const bgGeo = new PlaneGeometry(7, 6);
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  group.add(bg);
  disposables.push(bgGeo, bgMat);

  // ---- Lights (node-local rim/accent, scene provides ambient+key) ----
  const ambient = new AmbientLight(0xffffff, 0.45);
  group.add(ambient);
  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(2.5, 3.0, 3.0);
  group.add(key);
  const rim = new DirectionalLight(new Color(colors.accent), 0.9);
  rim.position.set(-3.0, 1.0, -2.0);
  group.add(rim);

  // ---- Filmstrip cards ----
  const strip = new Group();
  strip.rotation.y = -18 * Math.PI / 180;
  group.add(strip);

  const cardW = 1.6, cardH = 1.0, pitch = 1.85;
  const bevel = 0.025;
  const inkCol = new Color(colors.ink);

  const cardGeo = new PlaneGeometry(cardW, cardH);
  const frameGeo = new BoxGeometry(cardW + bevel * 2, cardH + bevel * 2, 0.05);
  disposables.push(cardGeo, frameGeo);

  const cardMats = [];
  const cardMeshes = [];
  const NUM = 5;
  const focusIndex = 2;

  const frameMatShared = new MeshPhysicalNodeMaterial();
  frameMatShared.color = inkCol;
  frameMatShared.roughness = 0.55;
  frameMatShared.metalness = 0.5;
  frameMatShared.clearcoat = 0.2;
  disposables.push(frameMatShared);

  for (let i = 0; i < NUM; i++) {
    const cardRoot = new Group();
    const offset = (i - focusIndex) * pitch;
    cardRoot.position.x = offset;

    const dist = Math.abs(i - focusIndex);
    const isFocus = i === focusIndex;
    const cScale = isFocus ? 1.0 : 0.92;
    const opacity = isFocus ? 1.0 : Math.max(0.55, 1.0 - dist * 0.22);

    if (isFocus) {
      // counter-rotate to face camera dead-on (undo strip rotation)
      cardRoot.rotation.y = 18 * Math.PI / 180;
    }
    cardRoot.scale.setScalar(cScale);

    // Frame
    const frame = new Mesh(frameGeo, frameMatShared);
    frame.position.z = -0.03;
    cardRoot.add(frame);

    // Card surface
    const mat = new MeshPhysicalNodeMaterial();
    mat.color = new Color(colors.surface);
    mat.roughness = 0.55;
    mat.metalness = 0.2;
    mat.clearcoat = 0.15;
    mat.transparent = true;
    mat.opacity = opacity;
    mat.side = DoubleSide;
    cardMats.push(mat);

    const card = new Mesh(cardGeo, mat);
    cardRoot.add(card);
    cardMeshes.push(card);

    // Caption below card
    const capText = captionList[i] || '';
    if (capText) {
      const cap = ctx.fontAtlas.createText(capText, {
        fontSize: 18,
        color: isFocus ? colors.paper : '#9aa0ac',
        align: 'center',
        letterSpacingPx: 2
      });
      cap.position.set(0, -(cardH / 2 + 0.28), 0.03);
      cap.scale.setScalar(1 / cScale);
      cardRoot.add(cap);
    }

    // Focused card accent underline bar
    if (isFocus) {
      const barGeo = new PlaneGeometry(1.6, 0.035);
      const barMat = new MeshBasicNodeMaterial();
      const acc = new Color(colors.accent);
      barMat.color = acc;
      barMat.colorNode = vec3(acc.r * 1.3, acc.g * 1.3, acc.b * 1.3);
      const bar = new Mesh(barGeo, barMat);
      bar.position.set(0, -(cardH / 2 + 0.12), 0.03);
      cardRoot.add(bar);
      disposables.push(barGeo, barMat);
    }

    strip.add(cardRoot);

    // load distinct texture (base only available; apply as map)
    if (config.imageUrl) {
      ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        // offset UV per card so subjects differ (internal parallax framing)
        try {
          tex.wrapS = tex.wrapT = 1000; // RepeatWrapping constant
          tex.offset.x = (i - focusIndex) * 0.06;
          tex.repeat.set(0.9, 0.9);
        } catch (e) { /* noop */ }
        mat.map = tex;
        mat.needsUpdate = true;
      });
    }
  }

  // ---- Headline & body text ----
  const headline = ctx.fontAtlas.createText(getText('headline', 'The collection'), {
    fontSize: 68,
    color: colors.paper,
    align: 'left'
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  const body = ctx.fontAtlas.createText(getText('body', 'Five calibres. One discipline.'), {
    fontSize: 26,
    color: '#c4c9d2',
    align: 'left'
  });
  body.position.set(-2.6, -1.5, 0);
  group.add(body);

  // ---- Entrance motion (weighted-settle) ----
  strip.scale.setScalar(0.96);
  const tlEnter = gsap.timeline();
  tlEnter.from(strip.position, { y: 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  tlEnter.to(strip.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power4.out' }, 0);
  tlEnter.to(strip.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.4, ease: 'power4.out' }, 0.5);
  tlEnter.from(headline.position, { y: 1.9, duration: 0.7, ease: 'power3.out' }, 0.1);
  tlEnter.from(body.position, { y: -1.9, duration: 0.7, ease: 'power2.out' }, 0.2);
  timelines.push(tlEnter);

  // ---- Idle: subtle breathing on focused card ----
  const tlIdle = gsap.timeline({ repeat: -1, yoyo: true });
  tlIdle.to(cardMeshes[focusIndex].scale, {
    x: 1.02, y: 1.02, duration: 4, ease: 'sine.inOut'
  });
  timelines.push(tlIdle);

  // ---- Apply cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(strip, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- Handlers ----
  group.userData.handlers = {
    click: () => ctx.emit?.('navigate', { to: 'hub-collection' })
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    primitiveHandles.forEach((h) => { try { h.cleanup && h.cleanup(); } catch (e) {} });
    cardMats.forEach((m) => {
      if (m.map) { try { m.map.dispose(); } catch (e) {} }
      m.dispose();
    });
    disposables.forEach((d) => { try { d.dispose && d.dispose(); } catch (e) {} });
  };

  return group;
}
